    vec3(1.0, 0.0, 0.0),  // EAST
    vec3(-1.0,0.0, 0.0),  // WEST
    vec3(0.0, 0.0, 1.0),  // SOUTH
    vec3(0.0, 0.0,-1.0)   // NORTH
